mapper.sql:
WHERE tenant_id = #{tenantId}
  AND delete_flag = 0

  AND (config_key LIKE CONCAT('%', CAST(#{keyword} AS VARCHAR), '%') OR description LIKE CONCAT('%', CAST(#{keyword} AS VARCHAR), '%'))

mapper.select:
SELECT * FROM system_config

ORDER BY config_key, id
LIMIT #{limit} OFFSET #{offset}
